const PRAXEN_MKT = false;
// PROVIDER -> MODEL Sankey (the-array LiteLLM). Source classified by api_base so VENICE
// (private cloud) and LOCAL split out of the openai-compatible api_provider bucket.
// query: sum by (api_provider, api_base, litellm_model_name) (increase(litellm_deployment_success_responses_total[$__range]))
// PRAXEN_MKT (injected by the generator) masks venice -> PRIVATE for marketing screenshots.
const MKT = (typeof PRAXEN_MKT !== 'undefined') && PRAXEN_MKT;
const isDark = !(context.grafana && context.grafana.theme && context.grafana.theme.isDark === false);
const T = isDark
  ? { bg:'transparent', text:'#EEF1F4', sub:'#8A939C', grid:'#2A3038', steel:'#8DA3BA', good:'#3F8F7E', signal:'#5AB0CE', signal2:'#8DA3BA', amber:'#C9A227', red:'#B85C5C', violet:'#A99BD1', phosphor:'#58C0A0', panel:'#0B0D10', border:'#2A3038' }
  : { bg:'transparent', text:'#0B0D10', sub:'#3A4651', grid:'#D2D7DD', steel:'#1B3A5C', good:'#2A6B5E', signal:'#0F536A', signal2:'#1B3A5C', amber:'#8A6D1F', red:'#8B3A3A', violet:'#5B4B8A', phosphor:'#147D64', panel:'#FFFFFF', border:'#D2D7DD' };
const MONO = 'JetBrains Mono, ui-monospace, SFMono-Regular, Menlo, Consolas, monospace';
const GLOW = isDark ? 10 : 0, GLOW_S = isDark ? 6 : 0;
function lastVal(fr) { if (!fr || !fr.fields) return 0; const v = fr.fields.find(f => f.type === 'number'); if (!v || !v.values) return 0; for (let i = v.values.length - 1; i >= 0; i--) { const n = Number(v.values[i]); if (Number.isFinite(n)) return n; } return 0; }
const frames = (context.panel && context.panel.data && context.panel.data.series) || [];

function sourceOf(prov, base) {
  const b = String(base || '').toLowerCase();
  if (b.indexOf('venice') >= 0) return 'private';   // venice ALWAYS masked in the sankeys (live + marketing)
  if (b.indexOf(':8888') >= 0 || b.indexOf('praxen-embed') >= 0) return 'local';
  if (b.indexOf('api.openai.com') >= 0) return 'openai';
  return String(prov || '?');
}
const SCOLOR = { venice:T.violet, private:T.violet, local:T.good, openai:T.signal2, anthropic:T.amber,
  gemini:T.signal, xai:T.violet, groq:T.red, mistral:T.signal2, perplexity:T.phosphor, huggingface:'#FFD21E', None:T.sub };
const CYCLE = [T.signal, T.amber, T.good, T.violet, T.red, T.signal2, T.phosphor];
function sColor(n, i) { return SCOLOR[n] || CYCLE[i % CYCLE.length]; }
function titleStyle(c) { return { color:c, fontFamily:MONO, fontSize:14, fontWeight:700, textShadowColor:isDark ? c : 'transparent', textShadowBlur:GLOW }; }

const SEP = ' ';
const linkMap = {}, sTot = {}, mTot = {};
for (const fr of frames) {
  const vf = fr.fields.find(f => f.type === 'number'); const labs = (vf && vf.labels) || {};
  const s = sourceOf(labs.api_provider, labs.api_base);
  let m = String(labs.litellm_model_name || ''); if (!m || m === '*') continue;
  if (s === 'private') m = 'private · models';   // venice models always collapsed — sankeys never reveal venice
  const v = lastVal(fr); if (!(v > 0)) continue;
  const k = s + SEP + m; linkMap[k] = (linkMap[k] || 0) + v; sTot[s] = (sTot[s] || 0) + v; mTot[m] = (mTot[m] || 0) + v;
}
if (!Object.keys(linkMap).length) {
  return { backgroundColor:T.bg, title:{ text:'PROVIDER → MODEL — NO DATA', subtext:'widen the time range',
    left:'center', top:'center', textStyle:titleStyle(T.amber), subtextStyle:{ color:T.sub, fontFamily:MONO, fontSize:12 } } };
}

// declutter: keep top-N models, collapse the tail into one node
const TOPN = 14;
const modelsSorted = Object.keys(mTot).sort((a, b) => mTot[b] - mTot[a]);
const keep = new Set(modelsSorted.slice(0, TOPN));
const tailN = modelsSorted.length - keep.size;
const TAIL = tailN > 0 ? ('… +' + tailN + ' models') : null;
const links2 = {}, mTot2 = {};
Object.keys(linkMap).forEach(k => {
  const i = k.indexOf(SEP), s = k.slice(0, i), m = k.slice(i + 1);
  const mm = keep.has(m) ? m : TAIL; if (!mm) return;
  const kk = s + SEP + mm; links2[kk] = (links2[kk] || 0) + linkMap[k]; mTot2[mm] = (mTot2[mm] || 0) + linkMap[k];
});

const srcSorted = Object.keys(sTot).sort((a, b) => sTot[b] - sTot[a]);
const modSorted = Object.keys(mTot2).sort((a, b) => mTot2[b] - mTot2[a]);
const nodes = [];
srcSorted.forEach((s, i) => { const c = sColor(s, i);
  nodes.push({ name:s, itemStyle:{ color:c, borderColor:c, borderWidth:1, shadowColor:isDark ? c : 'transparent', shadowBlur:GLOW_S },
    label:{ color:c, fontFamily:MONO, fontSize:13, fontWeight:700, textShadowColor:isDark ? c : 'transparent', textShadowBlur:GLOW_S,
      formatter:p => p.name.toUpperCase() + '  ' + Math.round(sTot[p.name] || 0) } }); });
modSorted.forEach(m => {
  nodes.push({ name:m, itemStyle:{ color:T.steel, borderColor:T.border, borderWidth:1 },
    label:{ color:T.text, fontFamily:MONO, fontSize:12,
      formatter:p => { let s = p.name; if (s.length > 30) s = s.slice(0, 29) + '…'; return s + '  ' + Math.round(mTot2[p.name] || 0); } } }); });
function grad(c) { try { return new echarts.graphic.LinearGradient(0, 0, 1, 0, [{ offset:0, color:c }, { offset:1, color:T.steel }]); } catch (e) { return c; } }
const links = Object.keys(links2).map(k => {
  const i = k.indexOf(SEP), s = k.slice(0, i), m = k.slice(i + 1);
  const c = sColor(s, srcSorted.indexOf(s));
  return { source:s, target:m, value:links2[k],
    lineStyle:{ color:grad(c), opacity:isDark ? 0.5 : 0.4, curveness:0.5, shadowColor:isDark ? c : 'transparent', shadowBlur:GLOW_S } };
});
const total = Math.round(Object.values(sTot).reduce((a, b) => a + b, 0));

return {
  backgroundColor:T.bg, textStyle:{ fontFamily:MONO, color:T.text },
  title:{ text:'PROVIDER → MODEL', subtext:'success responses · ' + total + ' calls · top ' + TOPN + ' models · range',
    left:14, top:10, textStyle:titleStyle(T.signal), subtextStyle:{ color:T.sub, fontFamily:MONO, fontSize:11 } },
  tooltip:{ trigger:'item', backgroundColor:T.panel, borderColor:T.border, textStyle:{ color:T.text, fontFamily:MONO, fontSize:12 },
    formatter:p => p.dataType === 'edge'
      ? (p.data.source.toUpperCase() + '  →  ' + p.data.target + '<br/><b>' + Math.round(p.data.value) + '</b> calls')
      : ('<b>' + p.name + '</b>') },
  series:[{ type:'sankey', left:16, right:248, top:62, bottom:24, nodeWidth:16, nodeGap:12, draggable:false, nodeAlign:'left',
    data:nodes, links:links, label:{ color:T.text, fontFamily:MONO, fontSize:12 }, lineStyle:{ color:'gradient', curveness:0.5 },
    emphasis:{ focus:'adjacency', lineStyle:{ opacity:0.9 }, label:{ fontWeight:700, textShadowColor:T.signal, textShadowBlur:GLOW } },
    levels:[{ depth:0, label:{ position:'right' } }, { depth:1, label:{ position:'right' } }] }]
};

const PRAXEN_MKT = false;

const frames = context.panel.data.series || [];
const isDark = !(context.grafana && context.grafana.theme && context.grafana.theme.isDark === false);
const PMKT = (typeof PRAXEN_MKT!=='undefined') && PRAXEN_MKT;
const T = isDark
  ? { bg:'transparent', text:'#EEF1F4', sub:'#8A939C', grid:'#2A3038', steel:'#8DA3BA', good:'#3F8F7E', signal:'#5AB0CE', signal2:'#8DA3BA', amber:'#C9A227', red:'#B85C5C', violet:'#A99BD1', phosphor:'#58C0A0', panel:'#0B0D10', border:'#2A3038' }
  : { bg:'transparent', text:'#0B0D10', sub:'#3A4651', grid:'#D2D7DD', steel:'#1B3A5C', good:'#2A6B5E', signal:'#0F536A', signal2:'#1B3A5C', amber:'#8A6D1F', red:'#8B3A3A', violet:'#5B4B8A', phosphor:'#147D64', panel:'#FFFFFF', border:'#D2D7DD' };
const GLOW = isDark ? 18 : 0, GLOW_S = isDark ? 12 : 0, MONO = 'monospace';
const lastVal = (f) => { if(!f) return 0; const v=f.fields.find((x)=>x.type==='number'); const a=v?v.values:[]; return a.length?+a[a.length-1]:0; };
const money = (v) => '$' + (Math.abs(v) < 1 ? v.toFixed(4) : v.toFixed(2));
const titleStyle = (c) => ({ color:c, fontSize:13, fontFamily:MONO, fontWeight:'bold' });
const xy = (f) => { if(!f) return []; const t=f.fields.find((x)=>x.type==='time'); const v=f.fields.find((x)=>x.type==='number'); if(!t||!v) return []; const tv=t.values, vv=v.values, out=[]; for(let i=0;i<tv.length;i++){ out.push([tv[i], vv[i]==null?0:+(+vv[i]).toFixed(2)]); } return out; };
const compact = (v) => { const n=Math.abs(v); if(n>=1e9) return (v/1e9).toFixed(1)+'B'; if(n>=1e6) return (v/1e6).toFixed(1)+'M'; if(n>=1e3) return (v/1e3).toFixed(1)+'k'; return ''+Math.round(v); };
const aggByLabel = (label) => { const a={}; frames.forEach((f)=>{ const v=f.fields.find((x)=>x.type==='number'); if(!v) return; let n=(v.labels&&v.labels[label]); n=(n===undefined||n===null||n==='')?'to-be-categorized':n; if(typeof n==='string' && n.indexOf('venice/')===0) n='private · provider'; a[n]=(a[n]||0)+Math.max(lastVal(f),0); }); return a; };

const isLocal=(m)=> m.indexOf('local-')===0 || m.indexOf('localwin-')===0;  // localwin-* = pre-Juliet local alias
const tierOf=(m)=> isLocal(m) ? 'LOCAL' : 'CLOUD';   // venice = private CLOUD (off-box), NOT its own tier
const tcolor={ LOCAL:T.good, CLOUD:T.signal };
const agg = aggByLabel('requested_model');   // venice already collapsed to 'private · provider' when PMKT
const TOPN=18;
const ms=Object.keys(agg).filter((m)=>agg[m]>0).sort((a,b)=>agg[b]-agg[a]);
const keep=new Set(ms.slice(0,TOPN));
const tail={};
const links=[]; const nset={};
ms.forEach((m)=>{ const val=agg[m]; const t=tierOf(m); const a='T · '+t;
  if(!keep.has(m)){ tail[t]=(tail[t]||0)+val; return; }
  nset[a]=1; nset[m]=1; links.push({source:a, target:m, value:+val.toFixed(0)}); });
Object.keys(tail).forEach((t)=>{ const a='T · '+t; const tgt='⋯ more '+t.toLowerCase(); nset[a]=1; nset[tgt]=1;
  links.push({source:a, target:tgt, value:+tail[t].toFixed(0)}); });
const empty=links.length===0;
const colorFor=(n)=>{ if(n.indexOf('T · ')===0) return tcolor[n.slice(4)]||T.sub;
  if(n.indexOf('⋯ more')===0) return T.sub;
  if(isLocal(n)) return T.good; if(n==='private · provider'||n.indexOf('venice/')===0) return T.violet; return T.signal2; };
const nodes=Object.keys(nset).map((n)=>({ name:n, itemStyle:{ color:colorFor(n), borderColor:T.bg } }));
return {
  backgroundColor:T.bg,
  title:{ text:'LOCAL ↔ CLOUD // token flow (range)', left:14, top:10, textStyle:titleStyle(T.violet),
    subtext:'on-box (local · $0) vs off-box (cloud · incl. private)', subtextStyle:{ color:T.sub, fontFamily:MONO, fontSize:11 } },
  graphic: empty ? [{ type:'text', left:'center', top:'middle',
    style:{ text:'NO TOKENS IN RANGE', fill:T.sub, font:'bold 14px monospace' } }] : [],
  tooltip:{ trigger:'item', backgroundColor:T.panel, borderColor:T.border,
    textStyle:{ color:T.text, fontFamily:MONO },
    formatter:(p)=> p.dataType==='edge'
      ? (String(p.data.source).replace('T · ','')+' → '+p.data.target+': '+p.data.value.toLocaleString()+' tok')
      : String(p.name).replace('T · ','') },
  series:[{ type:'sankey', left:16, right:208, top:58, bottom:20, nodeWidth:16, nodeGap:16, draggable:false,
    emphasis:{ focus:'adjacency' }, data:nodes, links:links,
    label:{ color:T.text, fontFamily:MONO, fontSize:12,
      formatter:(p)=>{ const s=String(p.name).replace(/^T · /,''); return s.length>26?s.slice(0,25)+'…':s; } },
    lineStyle:{ color:'gradient', opacity:isDark?0.5:0.45, curveness:0.5 },
    itemStyle:{ borderColor:T.bg, borderWidth:1 } }],
};
